// Generated by `factory render`. Do not edit.
// Which findings a change introduces. Only those are charged to the ticket; the others are on code the change did not
// write and become follow-ups.
//   lines       a finding counts when it is on a line the change added or changed (a new file counts whole): the
//               changed-lines rule the pre-commit hook and CI's lint already use.
//   merge-base  a finding counts when the merge-base does not have it. Findings are matched by fingerprint (tool,
//               rule, file, the normalised text of the line or the tool's own key), as a multiset, so a finding moved
//               by an edit above it is still the same finding and a second copy of one is a new one.
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const posix = (p) => p.split(path.sep).join('/');

// A path as a tool printed it, relative to the checkout (posix), or null when it is outside it.
export function relFile(root, printed) {
  if (!printed) return null;
  let p = String(printed).trim().replace(/^\.\//, '');
  if (path.isAbsolute(p) || /^[A-Za-z]:[\\/]/.test(p)) {
    const real = (x) => {
      try {
        return fs.realpathSync.native(x);
      } catch {
        return x;
      }
    };
    const rel = path.relative(real(root), real(p));
    if (rel.startsWith('..') || path.isAbsolute(rel)) return null;
    p = rel;
  }
  return posix(p);
}

const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

export function lineText(root, file, line, cache = new Map()) {
  if (!file || !line) return null;
  if (!cache.has(file)) {
    try {
      cache.set(file, fs.readFileSync(path.join(root, file), 'utf8').split(/\r?\n/));
    } catch {
      cache.set(file, null);
    }
  }
  const lines = cache.get(file);
  return lines?.[line - 1] ?? null;
}

// A finding's identity across rounds and against the merge-base, without its line number.
export function fingerprint(tool, f, text = null) {
  const what = f.key ?? (text != null && norm(text) ? norm(text) : norm(f.snippet) || norm(f.message));
  return createHash('sha256').update([tool, f.rule ?? '', f.file ?? '', what].join('\u0000')).digest('hex').slice(0, 16);
}

// Adds `file` (repository-relative), `fingerprint` and `tool` to a tool's raw findings, and a unique `id`
// (`tool:fp-<fingerprint>:<rule>`, with `~2`, `~3` after the fingerprint for further copies of the same finding).
// The fingerprint comes first and is prefixed: `tool:<rule>:<hex>` put a rule name such as generic-api-key directly
// before a hex string, which third-party secret scanners read as a posted API key (dogfood C23, owner report). Ids
// written before 0.2.85 are read through canonicalFindingId.
export function identify(root, toolId, raw) {
  const cache = new Map();
  const seen = new Map();
  return raw.map((f) => {
    const file = relFile(root, f.file);
    const fp = fingerprint(toolId, { ...f, file }, f.redacted ? null : lineText(root, file, f.line, cache));
    const n = (seen.get(fp) ?? 0) + 1;
    seen.set(fp, n);
    // A secret finding's `key` (a hash of the value) has done its work in the fingerprint; it is not recorded (a field named
    // key before a hash reads as a posted credential to secret scanners).
    const { key, ...rest } = f.redacted ? f : { ...f, key: f.key };
    return { ...rest, ...(f.redacted ? {} : { key }), tool: toolId, file, fingerprint: fp, id: findingId(f.rule, fp, n) };
  });
}

export const findingId = (rule, fp, n = 1) => `tool:fp-${fp}${n > 1 ? `~${n}` : ''}:${rule ?? 'unknown'}`;

// Either form, as the current one: `tool:<rule>:<fp>[~n]` (before 0.2.85) becomes `tool:fp-<fp>[~n]:<rule>`.
export function canonicalFindingId(id) {
  const s = String(id ?? '');
  if (/^tool:fp-/.test(s)) return s;
  const m = /^tool:(.+):([0-9a-f]{8,64})(~\d+)?$/.exec(s);
  return m ? `tool:fp-${m[2]}${m[3] ?? ''}:${m[1]}` : s;
}
export const sameFindingId = (a, b) => canonicalFindingId(a) === canonicalFindingId(b);

// Splits a tool's findings into the ones the change introduced and the pre-existing ones it can see.
//   scope     changed-lines | changed-files | repo
//   changed   Map file -> Set of changed line numbers, or null for a new file
//   base      the merge-base's findings of this tool (merge-base baseline)
// Findings outside the scope (another file, for a changed-* scope) are neither.
export function classify(findings, { scope, baseline, changed, base = [] }) {
  const onChangedLine = (f) => changed.has(f.file) && (changed.get(f.file) === null || (f.line != null && changed.get(f.file).has(f.line)));
  const inScope = (f) => scope === 'repo' || (f.file != null && changed.has(f.file));
  const budget = new Map();
  for (const b of base) budget.set(b.fingerprint, (budget.get(b.fingerprint) ?? 0) + 1);
  const introduced = [];
  const preexisting = [];
  for (const f of findings) {
    if (!inScope(f)) continue;
    let isNew;
    if (baseline === 'merge-base') {
      const left = budget.get(f.fingerprint) ?? 0;
      if (left > 0) budget.set(f.fingerprint, left - 1);
      isNew = left === 0;
    } else if (baseline === 'native') isNew = true;
    else isNew = onChangedLine(f);
    if (scope === 'changed-lines' && !onChangedLine(f)) isNew = false;
    (isNew ? introduced : preexisting).push(f);
  }
  return { introduced, preexisting };
}

// A rule engine given rule folders names each rule after the folder's path (Opengrep: "private.tmp.cache.rules.x.id").
// That prefix differs per machine and checkout, so it is cut off: rule ids, fingerprints and block lists stay stable.
export function stripRulePrefix(rule, dirs = [], cwd = '') {
  let best = '';
  for (const d of dirs) {
    let real = d;
    try {
      real = fs.realpathSync(d);
    } catch {
      /* as given */
    }
    for (const p of [d, real, path.relative(cwd || '.', d)]) {
      const dotted = p.split(/[\\/]+/).map((c) => c.replace(/^\.+/, '')).filter(Boolean).join('.');
      if (dotted && String(rule).startsWith(`${dotted}.`) && dotted.length > best.length) best = dotted;
    }
  }
  return best ? String(rule).slice(best.length + 1) : rule;
}

// ---- Tool-owned git worktrees --------------------------------------------------------------------------------------------
// A tool that makes its own git worktree (Opengrep's --baseline-commit checks out the baseline in one) must not run the
// repository's hooks there: a repository that installs hooks (core.hooksPath) runs them inside the tool's worktree, and the
// tool then cannot remove it, writes no output and the job "could not run" (held-out C21). Every tool process gets the
// hooks turned off for each git call it makes, through git's environment configuration (appended to any it already has,
// e.g. the extra header a CI checkout sets), and any worktree a tool leaves behind is removed afterwards.
export function toolGitEnv(env = process.env) {
  const n = Number(env.GIT_CONFIG_COUNT) || 0;
  return { ...env, GIT_CONFIG_COUNT: String(n + 1), [`GIT_CONFIG_KEY_${n}`]: 'core.hooksPath', [`GIT_CONFIG_VALUE_${n}`]: '/dev/null' };
}

const gitOut = (cwd, args) => spawnSync('git', args, { cwd, encoding: 'utf8', timeout: 60_000, env: toolGitEnv(process.env) });

// The worktree paths of the repository that holds `cwd` (realpaths; [] outside a repository).
export function worktreePaths(cwd) {
  const r = gitOut(cwd, ['worktree', 'list', '--porcelain']);
  if (r.status !== 0) return [];
  return String(r.stdout).split('\n').filter((l) => l.startsWith('worktree ')).map((l) => real(l.slice(9).trim()));
}
const real = (p) => {
  try {
    return fs.realpathSync(p);
  } catch {
    return p;
  }
};

// A tool process's own temporary folder (TMPDIR, TMP, TEMP) and git environment: a worktree the tool makes goes there, so
// what it leaves behind is told apart from the worktrees other runs add to the same repository meanwhile.
// { env, dir, cleanup(cwd) -> [removed worktree paths] }.
export function toolSandbox(env = process.env, { tmpRoot = os.tmpdir() } = {}) {
  const dir = real(fs.mkdtempSync(path.join(tmpRoot, 'factory-tool-')));
  return {
    dir,
    env: toolGitEnv({ ...env, TMPDIR: dir, TMP: dir, TEMP: dir }),
    cleanup(cwd) {
      const left = worktreePaths(cwd).filter((p) => p === dir || p.startsWith(`${dir}${path.sep}`));
      for (const p of left) gitOut(cwd, ['worktree', 'remove', '--force', p]);
      if (left.length) gitOut(cwd, ['worktree', 'prune']);
      fs.rmSync(dir, { recursive: true, force: true });
      return left;
    },
  };
}
